#!/usr/bin/env bash
# ==============================================================================
# Vision-judge re-scoring sweep, parallelized across checkpoints (one Slurm array
# task per checkpoint). Reuses captions already generated by the original sweep
# (evals/scripts/run_eval_array.sh) — no checkpoint loading, no generation step.
#
# Runs the host `eurovlm` venv directly (NOT the apptainer container): the
# container's bundled nvcc/CUDA-toolkit headers can't JIT-compile the Gated
# DeltaNet FlashInfer kernel that Qwen/Qwen3.8-27B-FP8 (a qwen3_5-architecture
# VLM) needs. Verified working end-to-end (image/multi_image/video, all 3
# modalities) via interactive smoke testing on the login node before this was
# written — see evals/scripts/rejudge_vision_test.sh for the small-scale version.
#
# Usage:
#   sbatch evals/scripts/rejudge_vision_array.sh
# ==============================================================================

#SBATCH --job-name=euro-vl-vjudge
#SBATCH --account=e-ext-2025e01-100
#SBATCH --partition=booster
#SBATCH --nodes=1
#SBATCH --ntasks-per-node=1
#SBATCH --gpus-per-node=1
#SBATCH --time=00:30:00
#SBATCH --array=0-4
#SBATCH --output=logs/euro_vl_eval/vjudge_array_%A_%a.out
#SBATCH --error=logs/euro_vl_eval/vjudge_array_%A_%a.err

set -uo pipefail
cd "$HOME/Megatron-Bridge"

# Compute nodes have no outbound network — the judge model is already cached
# locally (pulled during interactive smoke testing), so skip the metadata check
# huggingface_hub/vllm would otherwise make even for cached files.
export HF_HUB_OFFLINE=1
export PYTHONPATH="$PWD:${PYTHONPATH:-}"
export CUDA_HOME=/e/software/default/stages/2026/software/CUDA/13
# Isolated per-task FlashInfer JIT cache — sharing one cache dir across
# concurrently-running array tasks risked concurrent writes to the same
# generated build files (same GPU arch => same cache paths).
export FLASHINFER_WORKSPACE_BASE="/e/scratch/e-ext-2025e01-100/viveiros1/flashinfer_cache_job${SLURM_ARRAY_TASK_ID}"
mkdir -p "$FLASHINFER_WORKSPACE_BASE"

PY=/e/project1/e-ext-2025e01-100/viveiros1/envs/eurovlm/bin/python3
JUDGE_MODEL="Qwen/Qwen3.8-27B-FP8"

TAGS=(pil_50 pil_100 vect_10 vect_50 vect_100)
TAG="${TAGS[$SLURM_ARRAY_TASK_ID]}"

echo "=== $(date) | job $SLURM_JOB_ID task $SLURM_ARRAY_TASK_ID | node $SLURMD_NODENAME | $TAG ==="

# Manifests were built inside the apptainer container (container-internal media
# paths, /opt/Megatron-Bridge/...); this runs on the bare host, so rewrite them
# to real host paths first, once, into a per-task scratch dir.
MANIFEST_DIR="/e/scratch/e-ext-2025e01-100/viveiros1/vjudge_manifests_job${SLURM_ARRAY_TASK_ID}"
mkdir -p "$MANIFEST_DIR"
for modality in image multi_image video; do
  sed 's#/opt/Megatron-Bridge#'"$HOME"'/Megatron-Bridge#g' \
    "evals/data/${modality}_eval.jsonl" > "$MANIFEST_DIR/${modality}_eval.jsonl"
done

echo "--- starting vision judge (vLLM, host env, no container) ---"
"$PY" -m vllm.entrypoints.openai.api_server \
    --model "$JUDGE_MODEL" --port 8000 --max-model-len 40960 \
    --gpu-memory-utilization 0.85 --max-num-seqs 256 \
    > "logs/euro_vl_eval/vllm_vjudge_array_${SLURM_JOB_ID}_${SLURM_ARRAY_TASK_ID}.log" 2>&1 &
VLLM_PID=$!

cleanup() {
  echo "--- stopping vLLM (pid $VLLM_PID) $(date) ---"
  kill "$VLLM_PID" 2>/dev/null
  sleep 3
  kill -9 "$VLLM_PID" 2>/dev/null
}
trap cleanup EXIT

echo "--- waiting for judge to become healthy ---"
ready=0
for i in $(seq 1 90); do
  if curl -sS -m 3 http://localhost:8000/health >/dev/null 2>&1; then
    echo "judge healthy after $((i * 10))s"
    ready=1
    break
  fi
  if ! kill -0 "$VLLM_PID" 2>/dev/null; then
    echo "vLLM died during startup"
    break
  fi
  sleep 10
done
if [ "$ready" -ne 1 ]; then
  echo "judge never became healthy, aborting"
  exit 1
fi

for modality in image multi_image video; do
  manifest="$MANIFEST_DIR/${modality}_eval.jsonl"
  captions="evals/results/${TAG}/${modality}_captions.jsonl"
  [ -s "$captions" ] || { echo "skip $TAG/$modality: no captions"; continue; }
  echo "--- judge $TAG ($modality) $(date) ---"
  "$PY" -m evals.judge \
      --manifest "$manifest" \
      --captions "$captions" \
      --model_tag "$TAG" --judge_provider local --judge_model "$JUDGE_MODEL" \
      --out_dir evals/results/judged_vision
done

echo "=== $(date) | job $SLURM_JOB_ID task $SLURM_ARRAY_TASK_ID done ($TAG) ==="
